import type { CryptoKey } from "/home/akisarou/Projects/nts-lanes/helper2-crypto-modern/runtime/web-platform/src/crypto/crypto-key.ts";
export function supported(): number { return Number(SubtleCrypto.supports("digest", "SHA3-256")) + Number(SubtleCrypto.supports("generateKey", "ML-DSA-44")) + Number(SubtleCrypto.supports("generateKey", "ML-KEM-512")); }
export function existing(): number { return Number(SubtleCrypto.supports("digest", "SHA-256")); }
export function allNew(): number {
 let count=0;
 for (const name of ["SHA3-256", "SHA3-384", "SHA3-512"]) count += Number(SubtleCrypto.supports("digest", name));
 for (const name of ["cSHAKE128", "cSHAKE256"]) count += Number(SubtleCrypto.supports("digest", {name, length: 128}));
 for (const name of ["KMAC128", "KMAC256"]) count += Number(SubtleCrypto.supports("generateKey", {name, length: 128}));
 count += Number(SubtleCrypto.supports("generateKey", {name: "AES-OCB", length: 128}));
 count += Number(SubtleCrypto.supports("generateKey", "ChaCha20-Poly1305"));
 for (const name of ["Argon2d", "Argon2i", "Argon2id"]) count += Number(SubtleCrypto.supports("deriveBits", {name, nonce: new Uint8Array(8), memory: 8, parallelism: 1, passes: 1}, 128));
 for (const name of ["ML-DSA-44", "ML-DSA-65", "ML-DSA-87", "ML-KEM-512", "ML-KEM-768", "ML-KEM-1024"]) count += Number(SubtleCrypto.supports("generateKey", name));
 return count;
}

